<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\Event;

use Override;
use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\DcrInitialAccessToken;
use Civi\Lughauth\Shared\Event\PublicEvent;

class DcrInitialAccessTokenUpdateEvent extends DcrInitialAccessTokenEvent implements PublicEvent
{
    public function __construct(
        DcrInitialAccessToken $payload,
        public readonly DcrInitialAccessToken $original
    ) {
        parent::__construct($payload);
    }
    #[Override]
    public function eventType(): string
    {
        return 'dcr-initial-access-token.update';
    }
    #[Override]
    public function schemaVersion(): string
    {
        return 'v1';
    }
    #[Override]
    public function payload(): array
    {
        return $this->payload->asPublicJson();
    }
    #[Override]
    public function original(): array
    {
        return $this->original->asPublicJson();
    }
}
